import 'dart:async';import 'package:flutter/foundation.dart';import '../models/app_models.dart';import '../services/api_service.dart';import '../services/history_service.dart';import '../services/local_engine_service.dart';import '../services/settings_service.dart';
class AppState extends ChangeNotifier{AppState({required this.engine,required this.api,required this.history,required this.settings});final LocalEngineService engine;final ApiService api;final HistoryService history;final SettingsService settings;bool loading=true,processing=false,darkMode=false;int page=0;double progress=0;String status='Ready';String?inputPath,outputPath;String mode='static';EngineResult?lastResult;List<HistoryItem>items=[];late DesktopSettings config;
 Future<void>initialize()async{config=await settings.load();api.baseUrl=config.apiUrl;darkMode=config.darkMode;items=await history.load();loading=false;notifyListeners();}void setPage(int x){page=x;notifyListeners();}void selectInput(String?x){inputPath=x;notifyListeners();}void selectOutput(String?x){outputPath=x;notifyListeners();}void setMode(String x){mode=x;notifyListeners();}
 Future<void>compress()async{if(inputPath==null||outputPath==null)return;await _consume(engine.compress(python:config.python,workingDirectory:config.engineDirectory,input:inputPath!,output:outputPath!,mode:mode,checkpoint:config.checkpoint),'compress');}Future<void>decompress()async{if(inputPath==null||outputPath==null)return;await _consume(engine.decompress(python:config.python,workingDirectory:config.engineDirectory,input:inputPath!,output:outputPath!,checkpoint:config.checkpoint),'decompress');}
 Future<void>_consume(Stream<ProcessUpdate>s,String action)async{processing=true;status='Starting...';progress=.15;lastResult=null;notifyListeners();String?error;await for(final u in s){status=u.message;progress=u.done?1:(progress+.08).clamp(0.0,.9);lastResult=u.result;error=u.error;notifyListeners();}processing=false;final item=HistoryItem(id:DateTime.now().microsecondsSinceEpoch.toString(),action:action,inputPath:inputPath!,outputPath:outputPath!,mode:mode,createdAt:DateTime.now(),success:error==null,result:lastResult,error:error);items=[item,...items];await history.save(items);notifyListeners();}void cancel(){engine.cancel();processing=false;status='Cancelled';notifyListeners();}Future<void>clearHistory()async{items=[];await history.clear();notifyListeners();}Future<void>saveSettings()async{config.darkMode=darkMode;api.baseUrl=config.apiUrl;await settings.save(config);notifyListeners();}void toggleDark(bool x){darkMode=x;notifyListeners();}}
